const popup=document.getElementById('popup'),body=document.getElementById('body');let pinned=false,timer,active;function show(button,fix=false){clearTimeout(timer);active=button;pinned=fix;body.textContent=button.dataset.note;popup.hidden=false;const r=button.getBoundingClientRect();popup.style.left=Math.min(r.left,innerWidth-popup.offsetWidth-12)+'px';popup.style.top=Math.min(r.bottom+8,innerHeight-popup.offsetHeight-12)+'px';button.setAttribute('aria-expanded','true');}function close(){popup.hidden=true;pinned=false;active?.setAttribute('aria-expanded','false');}function delayedClose(){if(!pinned){clearTimeout(timer);timer=setTimeout(close,200);}}document.querySelectorAll('.term').forEach(button=>{button.setAttribute('aria-haspopup','dialog');button.setAttribute('aria-expanded','false');button.addEventListener('mouseenter',()=>{if(!pinned)show(button)});button.addEventListener('mouseleave',delayedClose);button.addEventListener('focus',()=>show(button));button.addEventListener('blur',()=>{if(!popup.contains(document.activeElement))delayedClose()});button.addEventListener('click',()=>show(button,true));});popup.addEventListener('mouseenter',()=>clearTimeout(timer));popup.addEventListener('mouseleave',delayedClose);document.getElementById('close').addEventListener('click',close);document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.addEventListener('click',e=>{if(!popup.contains(e.target)&&!e.target.closest('.term'))close()});